content.text:
        INSPECT: self._inspect,
    }

# -- helpers ---------------------------------------------------------
def _unit(self, identity):
    found = self.units.get((identity[0], identity[1]))
    if found is None or found[0] != identity[2]:
        return None
    return found

def _connection(self, identity):
    found = self.connections.get(identity[0])
    if found is None or found[0] != identity[1]:
        return None
    return found

def _file(self, identity):
    found = self.files.get(identity[0])
    if found is None or found[0] != identity[1]:
        return None
    return found

def _advance(self, epoch, state, service):
    if state == DENY:
        return DENY
    return self.images[epoch][1][state][self.column[service]]

def _new_context(self, unit, rid, epoch, state):
    self.context_id += 1
    unit[3][rid] = (epoch, state, self.context_id)
    unit[2] = rid
    self.live_contexts += 1
    self.images[epoch][3] += 1

# -- image lifecycle -------------------------------------------------
def _stage(self, event):
    epoch = event['epoch']
    if epoch <= self.epoch_hwm:
        return REJECTED
    text = event['policy']
    parsed = self.cache.get(text, False)
    if parsed is False:
        try:
            parsed = parse_policy(text)
        except PolicyError:
            parsed = None
        self.cache[text] = parsed
    if parsed is None:
        return REJECTED
    if text in self.published:
        machine, encoded = self.published[text]
    else:
        try:
            machine = compile_policy(parsed[0], self.order, self.column)
        except CompileError:
            machine = None
        if machine is None:
            encoded = None
        else:
            encoded = '{"accept":%s,"rows":%s}' % (
                _list(machine[0]), _rows(machine[1]))
        self.published[text] = (machine, encoded)
    if machine is None:
        return REJECTED
    if len(self.images) >= self.limits['images']:
        return REJECTED
    cells = machine[2]
    if self.cells + cells > self.limits['cells']:
        return REJECTED
    self.images[epoch] = [machine[0], machine[1], cells, 0]
    self.epoch_hwm = epoch
    self.cells += cells
    return '{"ok":true,"epoch":%d,"image":%s}' % (epoch, encoded)

def _commit(self, event):
    epoch = event['epoch']
    if epoch not in self.images:
        return REJECTED
    self.active = epoch
    return OK

def _retire(self, event):
    epoch = event['epoch']
    resident = self.images.get(epoch)
    if resident is None or epoch == self.active or resident[3]:
        return REJECTED
    del self.images[epoch]
    self.cells -= resident[2]
    return OK

# -- process identities ---------------------------------------------
def _spawn(self, event):
    namespace, pid, generation = event['unit']
    key = (namespace, pid)
    if key in self.units:
        return REJECTED
    if generation <= self.unit_gen.get(key, 0):
        return REJECTED
    service = event['service']
    if service not in self.column:
        return REJECTED
    if self.live_units >= self.limits['units']:
        return REJECTED
    self.units[key] = [generation, service, 0, {}]
    self.unit_gen[key] = generation
    self.live_units += 1
    return OK

def _clone(self, event):
    parent = self._unit(event['parent'])
    if parent is None:
        return REJECTED
    namespace, pid, generation = event['child']
    key = (namespace, pid)
    if key in self.units:
        return REJECTED
    if generation <= self.unit_gen.get(key, 0):
        return REJECTED
    if self.live_units >= self.limits['units']:
        return REJECTED
    source = parent[3]
